package ge.opensoft.openservice;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;import com.microsoft.playwright.options.AriaRole;import java.nio.file.Path;
final class MigrationRowsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception{String id=MigrationRowsAcceptance.seed(h.store);
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/migration-stops");page.locator("article").filter(new Locator.FilterOptions().setHasText(id)).getByRole(AriaRole.LINK,new Locator.GetByRoleOptions().setName("Inspect staged rows")).press("Enter");page.getByLabel("Rows per page").fill("1");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Show retained rows")).press("Enter");assertThat(page.locator("tbody tr")).hasCount(1);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Next rows")).press("Enter");assertThat(page.locator("tbody")).containsText(MigrationSource.key(2));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Previous rows")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect row").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("Retained <script>1");assertThat(page.locator("main script")).hasCount(0);
   for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/migration-rows-"+theme+".png")).setFullPage(true));}
   page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to staged rows")).press("Enter");page.getByLabel("Source phase").selectOption("sys_attachment");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Show retained rows")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect row").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("3 retained bytes");assertThat(page.locator("main")).containsText("SHA-256:");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to staged rows")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review reconciliation")).press("Enter");assertThat(page.locator("main")).containsText("Reconciliation");
  }
 }
}
